export function reviewWriteT(
  lang: AppLanguage,
  key: ReviewWriteMessageKey,
  vars?: Record<string, string | number>,
): string {
  const raw = MESSAGES[lang]?.[key] ?? MESSAGES.en[key] ?? key;
  if (!vars) return raw;
  return Object.entries(vars).reduce(
    (s, [k, v]) => s.split('{' + k + '}').join(String(v)),
    raw,
  );
}
